     3	/// How a clip's KIND is spelled in the chrome: its tint, its symbol and the
     4	/// one word that names it.
     5	///
     6	/// Four places show the same chip — the timeline clip's name strip, the
     7	/// timeline bar's selection block, the inspector's selection header and the
     8	/// Media tab — and they must agree, so the mapping lives here rather than four
     9	/// times over. It is spec §4.4's table ("video slate, audio green, still
    10	/// violet, text amber, shape teal, nest grey"), moved out of `TimelineView`
    11	/// now that three views other than the timeline read it.
    12	///
    13	/// **Every entry point takes the snapshot**, and that is the one substantive
    14	/// change to the old mapping. It used to answer for a `media` clip from
    15	/// `clip.enabled.video` alone, which is the DETACH switch, not a fact about
    16	/// the file: an imported mp3 has `enabled.video == true` (nothing ever turned
    17	/// it off) and so drew slate blue with a filmstrip icon and called itself
    18	/// "video" in two selection blocks. Only the media entry knows whether there
    19	/// are pixels, so the tests are `media.hasVideo` and `media.hasAudio`, exactly
    20	/// as `TimelineView.hasVideo` / `hasAudio` ask them — a clip reads as audio
    21	/// when it has no picture to show, whether that is because the file has none
    22	/// or because Detach Audio took it away.
    23	enum ClipKindStyle {
    24	    /// The kinds the chrome distinguishes. Not `ClipSource`'s cases: `media`
    25	    /// splits by what the file actually holds, and `still` and `image` share
    26	    /// one ink because both are a picture that does not move.
    27	    enum Kind {
    28	        case video
    29	        case audio
    30	        case still
    31	        case text
    32	        case shape
    33	        case graphic
    34	        case nest
    35	        case adjustment
    36	    }
    37	
    38	    static func kind(of clip: ClipSnapshot, in snapshot: ProjectSnapshot) -> Kind {
    39	        switch clip.source {
    40	        case .media:
    41	            let hasPicture = clip.enabled.video && (snapshot.media(for: clip)?.hasVideo ?? false)
    42	            return hasPicture ? .video : .audio
    43	        case .still, .image:
    44	            return .still
    45	        case .text:
    46	            return .text
    47	        case .shape:
    48	            return .shape
    49	        case .graphic:
    50	            return .graphic
    51	        case .nest:
    52	            return .nest
    53	        case .adjustment:
    54	            return .adjustment
    55	        }
    56	    }
    57	
    58	    /// The clip tint of spec §4.4, from `Theme.swift`'s tokens.
    59	    static func tint(for clip: ClipSnapshot, in snapshot: ProjectSnapshot) -> NSColor {
    60	        switch kind(of: clip, in: snapshot) {
    61	        case .video: return DS.clipVideo
    62	        case .audio: return DS.clipAudio
    63	        case .still: return DS.clipStill
    64	        case .text: return DS.clipText
    65	        case .shape: return DS.clipShape
    66	        // Shape's ink until road map 10's G5 gives a graphic a token.
    67	        case .graphic: return DS.clipShape
    68	        case .nest: return DS.clipNest
    69	        case .adjustment: return DS.clipAdjustment
    70	        }
    71	    }
    72	
    73	    /// The SF Symbol for a clip's kind, with the glyph to fall back to when
    74	    /// the symbol is missing (the `GhostButton` rule).
    75	    static func symbol(
    76	        for clip: ClipSnapshot, in snapshot: ProjectSnapshot
    77	    ) -> (name: String, fallback: String) {
    78	        switch kind(of: clip, in: snapshot) {
    79	        case .video: return ("film", "▦")
    80	        case .audio: return ("waveform", "∿")
    81	        case .still:
    82	            if case .still = clip.source { return ("snowflake", "❄") }
    83	            return ("photo", "▣")
    84	        case .text: return ("textformat", "T")
    85	        case .shape: return ("square.on.circle", "▭")
    86	        case .graphic: return ("curlybraces", "{}")
    87	        case .nest: return ("square.stack.3d.down.right", "▤")
    88	        case .adjustment: return ("camera.filters", "◐")
    89	        }
    90	    }
    91	
    92	    /// The lowercase word under a clip's name in a selection block.
    93	    static func name(for clip: ClipSnapshot, in snapshot: ProjectSnapshot) -> String {
    94	        switch kind(of: clip, in: snapshot) {
    95	        case .video: return "video"
    96	        case .audio: return "audio"
    97	        case .still:
    98	            if case .still = clip.source { return "still" }
    99	            return "image"
   100	        case .text: return "text"
   101	        case .shape: return "shape"
   102	        case .graphic: return "graphic"
   103	        case .nest: return "nest"
   104	        case .adjustment: return "adjustment"
   105	        }
   106	    }
   107	}

    override init(frame frameRect: NSRect) {
        super.init(frame: frameRect)
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("TimelineContentView does not support NSCoder")
    }

    // MARK: Regions

    /// Spec §4.4's split: a filmstrip over a waveform on a video clip with
    /// sound, the whole bar for one that has only the one.
    static func regions(
        in rect: CGRect, hasVideo: Bool, hasAudio: Bool
    ) -> (video: CGRect, audio: CGRect) {
        switch (hasVideo, hasAudio) {
        case (true, true):
            let top = (rect.height * 0.56).rounded()
            return (
                CGRect(x: rect.minX, y: rect.minY, width: rect.width, height: top),
                CGRect(
                    x: rect.minX, y: rect.minY + top, width: rect.width,
                    height: rect.height - top)
            )
        case (true, false): return (rect, .zero)
        case (false, true): return (.zero, rect)
        case (false, false): return (.zero, .zero)
        }
    }

    /// The square handle for one fade, at the audio region's corner when the
    /// fade is zero and at the fade's end once it has been dragged in.
    static func fadeRect(
        _ clip: ClipSnapshot, edge: TimelineEdge, audio: CGRect, layout: TimelineLayout
    ) -> CGRect {
        let props = clip.audioProps
        let side = TimelineLayout.fadeHandle
        let time = edge == .start ? clip.start + props.fadeIn : clip.end - props.fadeOut
        let x = min(max(layout.x(for: time), audio.minX), max(audio.maxX - side, audio.minX))
        return CGRect(x: x - (edge == .start ? 0 : side), y: audio.minY, width: side, height: side)
    }

    // MARK: Hit testing

    func hit(at point: CGPoint) -> TimelineHit {
        guard let owner = timeline else { return .none }
        let layout = owner.layout
        let snapshot = owner.snapshot

        if point.y >= owner.pinnedY, point.y < owner.pinnedY + TimelineLayout.rulerHeight {
            if point.x < owner.pinnedX + TimelineLayout.headerWidth { return owner.cornerHit }
            for marker in snapshot.markers
            where abs(layout.x(for: marker.time) - point.x) <= 6 {
                return .marker(marker.id)
            }
            return .ruler(max(layout.time(atX: point.x), 0))
        }

        if point.x < owner.pinnedX + TimelineLayout.headerWidth {
            guard let row = layout.row(atY: point.y) else { return .none }
            let local = CGPoint(x: point.x - owner.pinnedX, y: point.y - layout.rowTop(row))
            let lane = layout.trackHeight(row: row)
            if let button = TimelineHeaderView.button(at: local, height: lane) {
                return .headerButton(row: row, button: button)
            }
            return .header(row: row)
        }

        guard let row = layout.row(atY: point.y) else { return .outside }
        guard let track = owner.track(atRow: row) else { return .none }
        for clip in snapshot.clips(onTrack: track.id) {
            let rect = layout.clipRect(clip, row: row)
            guard point.x >= rect.minX - 1, point.x <= rect.maxX + 1 else { continue }
            guard !track.locked else { return .clip(clip.id) }
            if owner.hasAudio(clip) {
                // The same rectangle the waveform is drawn in
                // (`TimelineClipDrawing.contentRect`), never the lane rect —
                // the fade handles sit under the clip's name strip.
                let audio = Self.regions(
                    in: Self.contentRect(rect), hasVideo: owner.hasVideo(clip), hasAudio: true
                ).audio
                for edge in [TimelineEdge.start, TimelineEdge.end]
                where Self.fadeRect(clip, edge: edge, audio: audio, layout: layout)
                    .insetBy(dx: -2, dy: -2).contains(point) {
                    return .fade(clip.id, edge)
                }
            }
            if let hit = actionHit(clip, rect: rect, at: point) { return hit }
            // A bar too narrow to hold two grab zones is all body: trimming a
            // 3 pt clip by eye is not an interaction, it is a trap.
            if rect.width > TimelineLayout.edgeGrab * 3 {
                if point.x - rect.minX <= TimelineLayout.edgeGrab {
                    return .clipEdge(clip.id, .start)
                }
                if rect.maxX - point.x <= TimelineLayout.edgeGrab {
                    return .clipEdge(clip.id, .end)
                }
            }
            if let hit = volumeLineHit(clip, rect: rect, at: point) { return hit }
            return .clip(clip.id)
        }
        return .lane(row: row, time: max(layout.time(atX: point.x), 0))
    }

    // MARK: Mouse

    private func flags(_ event: NSEvent) -> NSEvent.ModifierFlags {
        event.modifierFlags.intersection(.deviceIndependentFlagsMask)
    }
